// The native file, picked by `nish-i32` in a native build: it reads the
// environment, which a wasm32 build refuses (NL2404), so a wasm32 build that
// picked this file would not compile.
import { getenv } from "nish:process";

export const seed = (): i32 => (getenv("NISH_S6_UNSET_VARIABLE") === null ? 100 : 101);
